<?php
declare(strict_types=1);
namespace Plati;
if(!defined('PLATI_ENTRY')&&PHP_SAPI!=='cli'){http_response_code(404);exit;}

final class Backups {
 static function archives(string $backup,array $data):array{$out=[];$dir=$backup.'.files';foreach($data['import_files']??[] as $file){$reference=$file['private_archive_reference'];$sha=$file['file_sha256'];if(!is_file($reference)||!hash_equals($sha,hash_file('sha256',$reference)))throw new Problem('Arhiva sursă lipsește sau diferă: '.$file['filename']);if(!is_dir($dir))mkdir($dir,0700,true);$ext=strtolower(pathinfo($reference,PATHINFO_EXTENSION));if(!preg_match('/^[a-z0-9]{1,8}$/D',$ext))$ext='bin';$name=$sha.'.'.$ext;$target=$dir.'/'.$name;if(!is_file($target)&&!copy($reference,$target))throw new Problem('Arhiva sursă nu a putut fi copiată.');if(!hash_equals($sha,hash_file('sha256',$target)))throw new Problem('Arhiva copiată nu trece verificarea.');$entry=['import_id'=>$file['id'],'name'=>$name,'sha256'=>$sha];if(is_file($reference.'.meta.json')){if(!copy($reference.'.meta.json',$target.'.meta.json'))throw new Problem('Metadata sursei nu a putut fi copiată.');$entry['sidecar_sha256']=hash_file('sha256',$target.'.meta.json');}$out[]=$entry;}return $out;}
 static function verifyArchives(string $backup,array $meta):array{$out=[];foreach($meta['archives']??[] as $archive){if(!preg_match('/^[a-f0-9]{64}\.[a-z0-9]{1,8}$/D',$archive['name']))throw new Problem('Nume de arhivă invalid.');$path=$backup.'.files/'.$archive['name'];if(!is_file($path)||!hash_equals($archive['sha256'],hash_file('sha256',$path)))throw new Problem('Arhiva originală nu a trecut verificarea backupului.');if(isset($archive['sidecar_sha256'])&&(!is_file($path.'.meta.json')||!hash_equals($archive['sidecar_sha256'],hash_file('sha256',$path.'.meta.json'))))throw new Problem('Metadata sursei nu a trecut verificarea.');$out[$archive['import_id']]=realpath($path);}return $out;}
 static function tableHash(array $rows):string{$canonical=[];foreach($rows as $row){$row=array_map(fn($v)=>$v===null?null:(string)$v,$row);$canonical[]=canonical($row);}sort($canonical,SORT_STRING);return hash('sha256',json($canonical));}
 static function verifyRestored(\PDO $db,array $expected):array{$hashes=[];foreach($expected as $table=>$rows){if(!preg_match('/^[a-z_]+$/D',$table))throw new Problem('Tabel invalid.');$actual=query($db,'SELECT * FROM `'.$table.'`')->fetchAll(\PDO::FETCH_ASSOC);$hashes[$table]=self::tableHash($actual);if(!hash_equals(self::tableHash($rows),$hashes[$table]))throw new Problem('Conținutul restaurat diferă pentru '.$table);}
  $keys=query($db,'SELECT TABLE_NAME,COLUMN_NAME,REFERENCED_TABLE_NAME,REFERENCED_COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND REFERENCED_TABLE_NAME IS NOT NULL')->fetchAll(\PDO::FETCH_ASSOC);foreach($keys as $fk){foreach($fk as $identifier)if(!preg_match('/^[a-z_]+$/D',$identifier))throw new Problem('Referință SQL invalidă.');$orphans=(int)query($db,'SELECT COUNT(*) FROM `'.$fk['TABLE_NAME'].'` child LEFT JOIN `'.$fk['REFERENCED_TABLE_NAME'].'` parent ON child.`'.$fk['COLUMN_NAME'].'`=parent.`'.$fk['REFERENCED_COLUMN_NAME'].'` WHERE child.`'.$fk['COLUMN_NAME'].'` IS NOT NULL AND parent.`'.$fk['REFERENCED_COLUMN_NAME'].'` IS NULL')->fetchColumn();if($orphans)throw new Problem('Referințe invalide după restaurare: '.$fk['TABLE_NAME']);}return ['table_hashes'=>$hashes,'foreign_keys_checked'=>count($keys)];
 }
 static function directory():string{$dir=config()['backup_directory']??storage().'/backups';if(!is_dir($dir))mkdir($dir,0700,true);return $dir;}
 static function create(\PDO $db,array $user):array{permit($user,'admin');$name='rebuild_'.gmdate('Ymd_His').'_'.bin2hex(random_bytes(5)).'.json.gz';$path=self::directory().'/'.$name;$tables=query($db,'SHOW TABLES')->fetchAll(\PDO::FETCH_COLUMN);$data=transaction($db,function()use($db,$tables){$out=[];foreach($tables as $t){if(!preg_match('/^[a-z_]+$/D',$t))throw new Problem('Tabel invalid.');$out[$t]=query($db,'SELECT * FROM `'.$t.'`')->fetchAll();}return $out;});$blob=gzencode(json(['format'=>'plati-rebuild-1','created_at'=>gmdate('c'),'tables'=>$data]),6);file_put_contents($path,$blob,LOCK_EX);chmod($path,0600);$archives=self::archives($path,$data);$sha=hash_file('sha256',$path);$decoded=json_decode(gzdecode(file_get_contents($path)),true,512,JSON_THROW_ON_ERROR);$counts=array_map('count',$data);if(array_map('count',$decoded['tables'])!==$counts)throw new Problem('Backupul nu a trecut verificarea.');$meta=['name'=>$name,'sha256'=>$sha,'rows'=>$counts,'created_at'=>gmdate('c'),'verified'=>true,'archives'=>$archives];file_put_contents($path.'.meta.json',json($meta),LOCK_EX);return $meta;}
 static function listing():array{$out=[];foreach(glob(self::directory().'/*.meta.json')?:[] as $file)$out[]=json_decode(file_get_contents($file),true);usort($out,fn($a,$b)=>strcmp($b['name'],$a['name']));return $out;}
 static function restoreLocal(string $path,string $target):array{if(PHP_SAPI!=='cli'||!preg_match('/^pg_rebuild_[a-f0-9]{8}$/D',$target)||$target===config()['database'])throw new Problem('Restaurarea de test cere o bază separată locală.');$meta=json_decode(file_get_contents($path.'.meta.json'),true);if(!hash_equals($meta['sha256'],hash_file('sha256',$path)))throw new Problem('Backup corupt.');$content=json_decode(gzdecode(file_get_contents($path)),true,512,JSON_THROW_ON_ERROR);if($content['format']!=='plati-rebuild-1')throw new Problem('Format backup invalid.');$archivePaths=self::verifyArchives($path,$meta);$c=config();$db=new \PDO('mysql:host='.$c['host'].';port='.$c['port'].';charset=utf8mb4',$c['user'],$c['password'],[\PDO::ATTR_ERRMODE=>\PDO::ERRMODE_EXCEPTION]);$db->exec('CREATE DATABASE `'.$target.'` CHARACTER SET utf8mb4 COLLATE utf8mb4_bin');$db->exec('USE `'.$target.'`');$sql=preg_replace('/^--.*$/m','',file_get_contents(__DIR__.'/../schema.sql'));foreach(explode(';',$sql) as $statement)if(trim($statement)!=='')$db->exec($statement);$db->exec('SET FOREIGN_KEY_CHECKS=0');try{transaction($db,function()use($db,$content){foreach($content['tables'] as $t=>$rows){if(!preg_match('/^[a-z_]+$/D',$t))throw new Problem('Tabel backup invalid.');foreach($rows as $row){$cols=array_keys($row);query($db,'INSERT INTO `'.$t.'`(`'.implode('`,`',$cols).'`) VALUES('.implode(',',array_fill(0,count($row),'?')).')',array_values($row));}}});}finally{$db->exec('SET FOREIGN_KEY_CHECKS=1');}$counts=[];foreach($content['tables'] as $t=>$rows){$counts[$t]=(int)query($db,'SELECT COUNT(*) FROM `'.$t.'`')->fetchColumn();if($counts[$t]!==count($rows))throw new Problem('Restaurare incompletă.');}$orphan=(int)query($db,'SELECT COUNT(*) FROM payment_resolutions r LEFT JOIN netopia_payments p ON p.id=r.payment_id LEFT JOIN invoices i ON i.id=r.invoice_id WHERE p.id IS NULL OR (r.invoice_id IS NOT NULL AND i.id IS NULL)')->fetchColumn();if($orphan)throw new Problem('Referințe invalide după restaurare.');$validation=self::verifyRestored($db,$content['tables']);foreach($archivePaths as $import=>$archive)query($db,'UPDATE import_files SET private_archive_reference=? WHERE id=?',[$archive,$import]);$validation['source_archives_verified']=count($archivePaths);return ['database'=>$target,'rows'=>$counts,'verified'=>true]+$validation;}
}
